import { spawn, type ChildProcessByStdio, type SpawnOptions } from "node:child_process";
import type { Readable } from "node:stream";

// Runs FFmpeg / ffprobe safely. Pure (no `server-only`) so the worker and tests share it.
//
// - Never through a shell: the binary and every argument are passed as an array, so no
//   value (file names are generated by us anyway) can be interpreted as a command.
// - A minimal environment (PATH only): no credentials or connection strings reach the
//   child process.
// - Inputs and outputs are local files only: callers add `-protocol_whitelist file` and
//   `file:` paths, so a crafted media file (HLS playlists, concat lists, tee, http…) can
//   never make FFmpeg open a network address or another local file.
// - A hard timeout and an AbortSignal: on either, the process is killed (SIGKILL) and
//   the run rejects. Output kept in memory is capped.
// - Pass 42: a process configured for the isolated media runner
//   (CREATOR_MEDIA_RUNNER_SOCKET set: the production worker) never runs FFmpeg itself —
//   this local path refuses, so a broken runner stops processing instead of silently
//   falling back to FFmpeg inside the worker, next to its credentials.

export class MediaToolError extends Error {
  constructor(
    readonly code: "timeout" | "aborted" | "failed" | "not_found" | "unavailable",
    readonly exitCode: number | null = null,
    /** The last part of stderr, for logs only (may name codecs, never secrets). */
    readonly detail = "",
  ) {
    super(`Media tool ${code}`);
    this.name = "MediaToolError";
  }
}

export interface RunOptions {
  readonly timeoutMs: number;
  readonly signal?: AbortSignal;
  readonly cwd?: string;
  /** Largest stdout kept (ffprobe JSON); the run fails beyond it. Default 1 MiB. */
  readonly maxStdoutBytes?: number;
}

const STDERR_TAIL = 4096;

export function runMediaTool(
  binary: string,
  args: readonly string[],
  options: RunOptions,
): Promise<{ readonly stdout: string }> {
  return new Promise((resolve, reject) => {
    if ((process.env.CREATOR_MEDIA_RUNNER_SOCKET ?? "") !== "") {
      reject(new MediaToolError("unavailable", null, "local execution disabled: media runner"));
      return;
    }
    if (options.signal?.aborted === true) {
      reject(new MediaToolError("aborted"));
      return;
    }
    const spawnOptions: SpawnOptions = {
      shell: false,
      stdio: ["ignore", "pipe", "pipe"],
      env: {
        PATH: process.env.PATH ?? "/usr/bin:/bin",
        LC_ALL: "C.UTF-8",
      } as unknown as NodeJS.ProcessEnv,
      windowsHide: true,
    };
    if (options.cwd !== undefined) spawnOptions.cwd = options.cwd;
    const child = spawn(binary, [...args], spawnOptions) as ChildProcessByStdio<
      null,
      Readable,
      Readable
    >;
    const maxStdout = options.maxStdoutBytes ?? 1024 * 1024;
    const out: Buffer[] = [];
    let outBytes = 0;
    let errTail = "";
    let settled = false;
    let reason: MediaToolError | null = null;

    const kill = (why: MediaToolError) => {
      reason ??= why;
      child.kill("SIGKILL");
    };
    const timer = setTimeout(() => {
      kill(new MediaToolError("timeout"));
    }, options.timeoutMs);
    const onAbort = () => {
      kill(new MediaToolError("aborted"));
    };
    options.signal?.addEventListener("abort", onAbort, { once: true });

    const finish = (error: Error | null, stdout = "") => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      options.signal?.removeEventListener("abort", onAbort);
      if (error === null) resolve({ stdout });
      else reject(error);
    };

    child.stdout.on("data", (chunk: Buffer) => {
      outBytes += chunk.length;
      if (outBytes > maxStdout) {
        kill(new MediaToolError("failed", null, "stdout too large"));
        return;
      }
      out.push(chunk);
    });
    child.stderr.on("data", (chunk: Buffer) => {
      errTail = (errTail + chunk.toString("utf8")).slice(-STDERR_TAIL);
    });
    child.on("error", (error: NodeJS.ErrnoException) => {
      finish(new MediaToolError(error.code === "ENOENT" ? "not_found" : "failed"));
    });
    child.on("close", (code) => {
      if (reason !== null) finish(reason);
      else if (code === 0) finish(null, Buffer.concat(out).toString("utf8"));
      else finish(new MediaToolError("failed", code, errTail));
    });
  });
}
